import{_ as t,o as r,c as n,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2025-02-26","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2025-02-26","date":"2025-02-26T00:00:00.000Z","updated":"2025-02-27T00:00:00.000Z","tags":["Ceph","RGW","Refactoring","Storage","Distributed System"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-02-26.md","filePath":"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-02-26.md","lastUpdated":1780459816000}'),s={name:"posts/2025/Ceph_RGW_Refactoring_Meeting_2025-02-26.md"};function a(i,e,l,g,_,c){return r(),n("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>: 2025-02-26<br><strong>参会人员</strong>: Yal, Kenal, Jesse, Cena, 以及其他 Ceph 开发人员</p><h4 id="_1-yal-的议题-bucket-logging-的授权与临时对象问题" tabindex="-1">1. <strong>Yal 的议题: Bucket Logging 的授权与临时对象问题</strong> <a class="header-anchor" href="#_1-yal-的议题-bucket-logging-的授权与临时对象问题" aria-label="Permalink to &quot;1. **Yal 的议题: Bucket Logging 的授权与临时对象问题**&quot;">​</a></h4><ul><li><strong>背景</strong>: 上周讨论了 Bucket Logging 的授权问题，Yal 已解决。目前问题在于确保未完成事务时不将临时对象提交到日志 Bucket。</li><li><strong>问题描述</strong>: 操作未完成时，日志可能会显示对象已添加，但实际上对象尚未完全上传。</li><li><strong>解决方案</strong>: 使用 CLS 引用计数器跟踪临时对象引用计数，在操作完成后减少计数，提交临时对象时循环等待事务完成，并创建带有永不减少的引用计数标记的对象以避免删除。</li><li><strong>后续行动</strong>: 实现方案，确保与对象复制操作兼容，并添加超时机制。</li></ul><h4 id="_2-kenal-的议题-在-rgw-中使用-reuse-port-选项" tabindex="-1">2. <strong>Kenal 的议题: 在 RGW 中使用 reuse_port 选项</strong> <a class="header-anchor" href="#_2-kenal-的议题-在-rgw-中使用-reuse-port-选项" aria-label="Permalink to &quot;2. **Kenal 的议题: 在 RGW 中使用 reuse_port 选项**&quot;">​</a></h4><ul><li><strong>背景</strong>: 当前 RGW 没有使用 <code>reuse_port</code> 选项。</li><li><strong>目标</strong>: 探索根据负载动态增加或减少 RGW 进程数量。</li><li><strong>讨论</strong>: 该功能仅在 Linux 内核 3.9 及以上版本中可用，建议将其设为默认配置或通过配置标志启用。</li><li><strong>决定</strong>: 由于大多数支持的 Linux 发行版内核版本满足要求，建议直接启用该选项。</li><li><strong>后续行动</strong>: Kenal 将检查所有支持的 Linux 发行版的内核版本，并提交 PR。</li></ul><h4 id="_3-jesse-的议题-pr-审查请求" tabindex="-1">3. <strong>Jesse 的议题: PR 审查请求</strong> <a class="header-anchor" href="#_3-jesse-的议题-pr-审查请求" aria-label="Permalink to &quot;3. **Jesse 的议题: PR 审查请求**&quot;">​</a></h4><ul><li><strong>背景</strong>: Jesse 请求审查一个涉及 RGW 修改的 PR。</li><li><strong>状态</strong>: 测试结果显示部分失败，Jesse 希望有经验的开发人员帮助分析失败原因。</li><li><strong>后续行动</strong>: Jesse 将继续分析测试失败原因，并在 PR 中更新相关信息。</li></ul><h4 id="_4-cena-的议题-编码版本与-osd-版本依赖" tabindex="-1">4. <strong>Cena 的议题: 编码版本与 OSD 版本依赖</strong> <a class="header-anchor" href="#_4-cena-的议题-编码版本与-osd-版本依赖" aria-label="Permalink to &quot;4. **Cena 的议题: 编码版本与 OSD 版本依赖**&quot;">​</a></h4><ul><li><strong>背景</strong>: 讨论了如何在编码版本中处理字段删除问题。</li><li><strong>问题描述</strong>: 当前编码版本中，某些字段可能在某些 OSD 版本中不再需要，但为了避免兼容性问题，仍需保留这些字段。</li><li><strong>讨论</strong>: 是否可以通过 OSD 版本映射来决定是否编码/解码某些字段。</li><li><strong>决定</strong>: 保持现有编码结构，仅在函数调用中移除不必要的参数。</li><li><strong>后续行动</strong>: Cena 将修改 PR，移除不必要的函数参数。</li></ul><h4 id="_5-seth-steering-committee-更新" tabindex="-1">5. <strong>Seth Steering Committee 更新</strong> <a class="header-anchor" href="#_5-seth-steering-committee-更新" aria-label="Permalink to &quot;5. **Seth Steering Committee 更新**&quot;">​</a></h4><ul><li><strong>背景</strong>: Seth Steering Committee 正在讨论 Ceph 下一个版本（Tentacle）的发布时间。</li><li><strong>决定</strong>: 计划在未来一两个月内进行代码冻结。</li><li><strong>后续行动</strong>: 如有未完成的功能需要纳入 Tentacle 版本，请及时与 Adam 或 Eric 联系。</li></ul><p><strong>会议结束</strong></p>',13)])])}const d=t(s,[["render",a]]);export{u as __pageData,d as default};
